const numbers = [28568, 28565, 28562, 28561, 28560];
const settled = await Promise.allSettled(
  numbers.map(number => tools.mcp__lesson__read_pull_request({ number }))
);
const output = settled.map((entry, i) => {
  if (entry.status === "rejected") {
    return { number: numbers[i], lookup: "failed", error: String(entry.reason) };
  }
  const blocks = Array.isArray(entry.value?.content) ? entry.value.content : [];
  const texts = blocks.filter(b => b?.type === "text" && typeof b.text === "string");
  const parsed = texts.map(b => {
    try { return JSON.parse(b.text); }
    catch { return { parse_error: true, text: b.text }; }
  });
  return {
    number: numbers[i],
    lookup: entry.value?.isError ? "tool_error" : "succeeded",
    parsed
  };
});
text(JSON.stringify(output));
